def _allclose_vla(a, b, rtol=1e-05, atol=1e-08):
    """
    Compare two elements of variable length array (VLA) columns, returning
    ``True`` if they are equal within the given tolerances and ``False``
    otherwise.

    Unlike regular columns, each element of a VLA column is itself an array of
    (possibly zero) elements, so the two elements may even have different
    shapes; ``np.allclose`` alone would happily broadcast e.g. an array of one
    element against an array of two elements.
